verify:
choices = {o: choices[n] for o, n in {'C': 'A', 'D': 'B', 'B': 'C', 'A': 'D'}.items()}; answer = {'A': 'C', 'B': 'D', 'C': 'B', 'D': 'A'}[answer]  # shuffled: original letters
def iv(s, v):
    u = s.strip()[2:-2].replace('\\le', '<=').replace('\\ge', '>=')
    if u.startswith(v + ' '):
        return value(u).as_set()
    L, Rt = u.split(' ' + v + ' ')
    return value(L + ' ' + v).as_set() & value(v + ' ' + Rt).as_set()
x = symbols('x')
S = Interval(3, 8)
assert S == solve_univariate_inequality(2*x - 1 >= 5, x, relational=False) & solve_univariate_inequality(2*x - 1 <= 15, x, relational=False)
ok = [k for k in choices if iv(choices[k], 'x') == S]
assert ok == [answer]
